import * as L from './assets/leaflet.js';
import {climateValue} from './climate-view.js';
import {hailAge} from './hail-map.js';
import {esc,miniWeather,numeric} from './weather-tools.js';
export function mountAtlasMap(host,{center,cities,onCity,onPoint,onError}){
 host.replaceChildren();const map=L.map(host,{zoomControl:false,scrollWheelZoom:false,worldCopyJump:true,minZoom:2,maxZoom:17}).setView([center.latitude,center.longitude],7);
 const base=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'}).addTo(map);let failures=0;base.on('tileerror',()=>{if(++failures===3)onError?.('La mappa non si carica. Puoi usare il globo o aprire Google Maps.')});
 const pins=L.layerGroup().addTo(map);let radar=null,coverage=null,currentLayer='meteo',points=cities;
 function draw(){pins.clearLayers();const report=['grandine','segnalazioni'].includes(currentLayer),groups=[];for(const c of points){if(report&&!c.reportCount)continue;const p=map.latLngToContainerPoint([c.latitude,c.longitude]),size=map.getSize();if(p.x<0||p.x>size.x||p.y<0||p.y>size.y)continue;const group=groups.find(g=>Math.abs(g.pixel.x-p.x)<(currentLayer==='grandine'?205:155)&&Math.abs(g.pixel.y-p.y)<(currentLayer==='grandine'?80:55));if(group)group.cities.push(c);else groups.push({pixel:p,cities:[c]})}for(const group of groups){if(group.cities.length>1){const all=group.cities,lat=all.reduce((a,c)=>a+c.latitude,0)/all.length,lon=all.reduce((a,c)=>a+c.longitude,0)/all.length;L.marker([lat,lon],{title:all.map(c=>c.name).join(', '),keyboard:true,icon:L.divIcon({className:'atlas-pin-wrap',html:`<div class="atlas-map-pin atlas-cluster">${all.length} città · ingrandisci</div>`,iconSize:[120,44],iconAnchor:[60,22]})}).on('click',()=>map.fitBounds(all.map(c=>[c.latitude,c.longitude]),{padding:[50,50],maxZoom:13})).addTo(pins);continue}const c=group.cities[0],w=c.current,value=climateValue(w,currentLayer);let extra='';if(currentLayer==='grandine')extra=`<b>◇ ${c.reportCount} segnalazioni</b><small>${hailAge(c.lastReport)}</small>`;else if(report)extra=`<b>${c.reportCount} post</b>`;else if(value!==null)extra=`<b>${value}</b>`;else if(currentLayer==='pioggia')extra=`<b>${numeric(w?.precipitation)?w.precipitation+' mm':'—'}</b>`;else if(currentLayer==='vento')extra=`<b>${numeric(w?.wind_speed_10m)?w.wind_speed_10m+' km/h':'—'}</b>`;else if(currentLayer==='nuvole')extra=`<b>${numeric(w?.cloud_cover)?w.cloud_cover+'%':'—'}</b>`;else if(w)extra=miniWeather(w.weather_code,w.is_day!==0)+`<b>${Math.round(w.temperature_2m)}°</b>`;
 const marker=L.marker([c.latitude,c.longitude],{title:currentLayer==='grandine'?c.name+' · grandine segnalata · '+hailAge(c.lastReport):c.name,keyboard:true,icon:L.divIcon({className:'atlas-pin-wrap',html:`<div class="atlas-map-pin ${currentLayer==='grandine'?'hail-map-pin':''} ${c.selected?'selected':''}"><span>${esc(c.name)}</span>${extra}</div>`,iconSize:currentLayer==='grandine'?[190,70]:[120,42],iconAnchor:currentLayer==='grandine'?[95,35]:[60,21]})});marker.on('click',()=>onCity(c));marker.addTo(pins)}}
 function clearRadar(){if(radar)map.removeLayer(radar);if(coverage)map.removeLayer(coverage);radar=null;coverage=null}
 map.on('click',e=>onPoint({latitude:e.latlng.lat,longitude:((e.latlng.lng+180)%360+360)%360-180}));map.on('moveend',draw);draw();const ro=new ResizeObserver(()=>map.invalidateSize());ro.observe(host);
 return {clearRadar,setCities(value){points=value;draw()},setLayer(value){currentLayer=value;if(value!=='radar')clearRadar();draw()},setRadar(source,frame){clearRadar();let errs=0;coverage=L.tileLayer(source.host+'/v2/coverage/0/512/{z}/{x}/{y}/0/0_0.png',{maxNativeZoom:7,maxZoom:17,opacity:.25,pane:'overlayPane'}).addTo(map);radar=L.tileLayer(source.host+frame.path+'/512/{z}/{x}/{y}/2/1_1.png',{maxNativeZoom:7,maxZoom:17,opacity:.78,attribution:'Radar: <a href="https://www.rainviewer.com/" target="_blank" rel="noopener">RainViewer</a>'}).addTo(map);radar.on('tileerror',()=>{if(++errs===2)onError?.('Immagini radar non disponibili in questa vista. Riprova.')});},zoom(factor){factor>1?map.zoomIn():map.zoomOut()},focus(p){map.setView([p.latitude,p.longitude],7)},dispose(){ro.disconnect();map.remove()}};
}
